  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (m) { let v=m[2]; if(v.startsWith('"')&&v.endsWith('"'))v=v.slice(1,-1); process.env[m[1]]=v; }
}
function deriveKey(){ return scryptSync(process.env.AUTH_SECRET,'nxeon-byok',32); }
function dec(enc){ if(!enc)return null; try{const[a,b,c]=enc.split(':');const d=createDecipheriv('aes-256-gcm',deriveKey(),Buffer.from(a,'base64'));d.setAuthTag(Buffer.from(b,'base64'));return Buffer.concat([d.update(Buffer.from(c,'base64')),d.final()]).toString('utf8');}catch(e){return null;} }
const { PrismaClient } = await import('/opt/nxeon/node_modules/@prisma/client/index.js');
const p = new PrismaClient();
const s = await p.server.findUnique({ where:{id:'cmsc9l72y000ghl7iyd87u5ja'}, include:{ dedicatedIp:true } });
