    public async Task<RevenueForecastDto> GetRevenueForecastAsync(DateTime asOfUtc)
    {
        asOfUtc = DateTime.SpecifyKind(asOfUtc, DateTimeKind.Utc);
        var nowLocal = asOfUtc + StudioUtcOffset;

        // Local calendar boundary → back to a UTC instant for the Mongo query.
        DateTime ToUtc(DateTime local) =>
            DateTime.SpecifyKind(local - StudioUtcOffset, DateTimeKind.Utc);

        var todayLocal = nowLocal.Date;
        var todayStart = ToUtc(todayLocal);
        var todayEnd = ToUtc(todayLocal.AddDays(1));
        var tomorrowStart = todayEnd;
        var tomorrowEnd = ToUtc(todayLocal.AddDays(2));

        // ISO week (Monday-anchored) containing the local "today".
        var dow = ((int)todayLocal.DayOfWeek + 6) % 7; // Mon=0 … Sun=6
        var weekMondayLocal = todayLocal.AddDays(-dow);
        var weekStart = ToUtc(weekMondayLocal);
        var weekEnd = ToUtc(weekMondayLocal.AddDays(7));

        var monthFirstLocal = new DateTime(todayLocal.Year, todayLocal.Month, 1, 0, 0, 0);
        var monthStart = ToUtc(monthFirstLocal);
        var monthEnd = ToUtc(monthFirstLocal.AddMonths(1));

        var windows = new (string Period, DateTime Start, DateTime End)[]
        {
            ("TODAY", todayStart, todayEnd),
            ("TOMORROW", tomorrowStart, tomorrowEnd),
            ("THIS_WEEK", weekStart, weekEnd),
            ("THIS_MONTH", monthStart, monthEnd),
        };

        RevenueForecastDto Empty()
        {
            RevenueForecastPeriodDto P(string name, DateTime s, DateTime e) =>
                new() { Period = name, WindowStartUtc = s, WindowEndUtc = e };
            return new RevenueForecastDto
            {
                Today = P("TODAY", todayStart, todayEnd),
                Tomorrow = P("TOMORROW", tomorrowStart, tomorrowEnd),
                ThisWeek = P("THIS_WEEK", weekStart, weekEnd),
                ThisMonth = P("THIS_MONTH", monthStart, monthEnd),
                ComputedAtUtc = DateTime.UtcNow,
            };
        }

        // We forecast only what is STILL TO COME: every window's effective lower
        // bound is max(windowStart, now). Load upcoming sessions from now until the
        // furthest window end so the week bucket stays complete even when it spills
        // past month-end.
        var loadUntil = windows.Max(w => w.End);
        if (loadUntil <= asOfUtc) return Empty();

        var sessions = await _sessions
            .Find(Builders<CalendarSession>.Filter.And(
                Builders<CalendarSession>.Filter.Gte(s => s.StartTime, asOfUtc),
                Builders<CalendarSession>.Filter.Lt(s => s.StartTime, loadUntil),
                Builders<CalendarSession>.Filter.Eq(s => s.Status, "SCHEDULED"),
                Builders<CalendarSession>.Filter.Eq(s => s.IsFreelance, false)))
            .Project(s => new
            {
                s.Id,
                s.StartTime,
                s.Format,
                s.ClassBlueprintId,
                s.DropInPrice,
                s.Origin,
                s.BlockedReason,
            })
            .ToListAsync();

        // Drop admin blocks / non-class holds — they carry no bookable revenue.
        var classSessions = sessions
            .Where(s => !string.IsNullOrEmpty(s.Id)
                        && s.Origin != "BLOCK"
                        && string.IsNullOrEmpty(s.BlockedReason))
            .ToList();
        if (classSessions.Count == 0) return Empty();

        var sessionById = classSessions.ToDictionary(s => s.Id!);
        var sessionIds = classSessions.Select(s => s.Id!).ToList();

        // Per-session drop-in price = the session's price snapshot, else the live
        // blueprint price (historical-integrity fallback, mirrors POS behaviour).
        var needBlueprintPrice = classSessions
            .Where(s => (s.DropInPrice ?? 0m) <= 0m && !string.IsNullOrEmpty(s.ClassBlueprintId))
            .Select(s => s.ClassBlueprintId!)
            .Distinct()
            .ToList();
        var blueprintPrice = new Dictionary<string, decimal>();
        if (needBlueprintPrice.Count > 0)
        {
            var bps = await _blueprints
                .Find(Builders<ClassBlueprint>.Filter.In(b => b.Id, needBlueprintPrice))
                .Project(b => new { b.Id, b.DropInPrice })
                .ToListAsync();
            foreach (var b in bps)
                if (!string.IsNullOrEmpty(b.Id)) blueprintPrice[b.Id!] = b.DropInPrice;
        }

        decimal PriceOfSession(string sessionId)
        {
            var s = sessionById[sessionId];
            if ((s.DropInPrice ?? 0m) > 0m) return s.DropInPrice!.Value;
            if (!string.IsNullOrEmpty(s.ClassBlueprintId)
                && blueprintPrice.TryGetValue(s.ClassBlueprintId!, out var bp)) return bp;
            return 0m;
        }

        // Active UPCOMING bookings on those sessions (a held or confirmed seat).
        var bookings = await _attendances
            .Find(Builders<Attendance>.Filter.And(
                Builders<Attendance>.Filter.In(a => a.CalendarSessionId, sessionIds),
                Builders<Attendance>.Filter.In(a => a.Status, UpcomingBookedStatuses)))
            .Project(a => new
            {
                a.CalendarSessionId,
                a.ClientId,
                a.Quantity,
                a.PaymentMethod,
                a.PackageInstanceId,
            })
            .ToListAsync();
        if (bookings.Count == 0) return Empty();

        // Client credit balances by format bucket. A booking by a client who
        // already holds credits covering that class type is treated as ALREADY
        // PAID → 0 forecast revenue. We consume the balance chronologically so a
        // client with N credits and >N future bookings only zeroes out N of them;
        // the rest fall back to their drop-in price.
        var clientIds = bookings
            .Where(b => !string.IsNullOrEmpty(b.ClientId) && b.ClientId != EmptyObjectId)
            .Select(b => b.ClientId)
            .Distinct()
            .ToList();

        // (clientId → (bucket → remaining credits)). Only ACTIVE / LOW_BALANCE
        // packages with credits left and not already expired as of now count.
        var creditBalance = new Dictionary<string, Dictionary<string, int>>();
        if (clientIds.Count > 0)
        {
            var pkgs = await _clientPackages
                .Find(Builders<ClientPackage>.Filter.And(
                    Builders<ClientPackage>.Filter.In(p => p.ClientId, clientIds),
                    Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),
                    Builders<ClientPackage>.Filter.Gt(p => p.CreditsRemaining, 0)))
                .Project(p => new { p.ClientId, p.Format, p.CreditsRemaining, p.ExpiryDate })
                .ToListAsync();
            foreach (var p in pkgs)
            {
                if (string.IsNullOrEmpty(p.ClientId)) continue;
                if (p.ExpiryDate.HasValue && p.ExpiryDate.Value <= asOfUtc) continue; // already lapsed
                var bucket = CreditBucketForFormat(p.Format);
                if (!creditBalance.TryGetValue(p.ClientId, out var byBucket))
                    creditBalance[p.ClientId] = byBucket = new Dictionary<string, int>();
                byBucket[bucket] = byBucket.GetValueOrDefault(bucket, 0) + p.CreditsRemaining;
            }
        }

        // Walk every upcoming booking in start-time order so credit consumption is
        // chronologically honest, then bucket each into the windows it falls in.
        var ordered = bookings
            .Where(b => !string.IsNullOrEmpty(b.CalendarSessionId)
                        && sessionById.ContainsKey(b.CalendarSessionId!))
            .OrderBy(b => sessionById[b.CalendarSessionId!].StartTime)
            .ToList();

        var acc = windows.ToDictionary(w => w.Period, _ => new RevenueForecastPeriodDto());
        foreach (var (period, _, _) in windows)
        {
            acc[period].Period = period;
        }

        foreach (var b in ordered)
        {
            var session = sessionById[b.CalendarSessionId!];
            var startUtc = session.StartTime;
            var qty = b.Quantity <= 0 ? 1 : b.Quantity;
            var price = PriceOfSession(b.CalendarSessionId!);
            var bucket = CreditBucketForFormat(session.Format);

            // How many of this booking's seats are covered by a package credit.
            var explicitCredit = string.Equals(b.PaymentMethod, "PACKAGE_CREDIT", StringComparison.OrdinalIgnoreCase)
                                  || !string.IsNullOrEmpty(b.PackageInstanceId);

            int coveredSeats;
            var hasClient = !string.IsNullOrEmpty(b.ClientId)
                            && creditBalance.TryGetValue(b.ClientId!, out _);
            var available = 0;
            if (hasClient) creditBalance[b.ClientId!].TryGetValue(bucket, out available);

            if (explicitCredit)
            {
                // Already flagged to pay by credit → fully covered (already paid).
                coveredSeats = qty;
                if (hasClient) creditBalance[b.ClientId!][bucket] = Math.Max(0, available - qty);
            }
            else
            {
                coveredSeats = Math.Min(available, qty);
                if (coveredSeats > 0) creditBalance[b.ClientId!][bucket] = available - coveredSeats;
            }

            var chargedSeats = qty - coveredSeats;
            var revenue = chargedSeats * price;
            var isChargeable = chargedSeats > 0 && price > 0m;

            foreach (var (period, wStart, wEnd) in windows)
            {
                // Only count what is still to come inside the window.
                var lower = wStart > asOfUtc ? wStart : asOfUtc;
                if (startUtc < lower || startUtc >= wEnd) continue;
                var slot = acc[period];
                slot.TotalBookings += 1;
                slot.ForecastVnd += revenue;
                if (isChargeable) slot.ChargeableBookings += 1;
                else slot.CreditCoveredBookings += 1;
            }
        }

        foreach (var (period, wStart, wEnd) in windows)
        {
            acc[period].WindowStartUtc = wStart;
            acc[period].WindowEndUtc = wEnd;
        }

        return new RevenueForecastDto
        {
            Today = acc["TODAY"],
            Tomorrow = acc["TOMORROW"],
            ThisWeek = acc["THIS_WEEK"],
            ThisMonth = acc["THIS_MONTH"],
            ComputedAtUtc = DateTime.UtcNow,
        };
    }

    // ── Show Rate: new vs recurring (card cmsj1mpq00018hljajup3qtb3) ──────────
    //
    // Show rate = attended ÷ booked over the selected period, where:
    //   • "booked"   = FINALIZED attendances whose session started in the window —
