    private async Task<(decimal revenue, decimal fees)> SumCollectedAsync(DateTime start, DateTime end)
    {
        var payments = await _payments
            .Find(Builders<Payment>.Filter.And(
                Builders<Payment>.Filter.Gte(p => p.PaymentDate, start),
                Builders<Payment>.Filter.Lt(p => p.PaymentDate, end)))
            .Project(p => new PaymentRevenueRow { InvoiceId = p.InvoiceId, AmountPaid = p.AmountPaid })
            .ToListAsync();
        if (payments.Count == 0) return (0m, 0m);

        var invoiceIds = payments
            .Where(p => !string.IsNullOrEmpty(p.InvoiceId))
            .Select(p => p.InvoiceId!)
            .Distinct()
            .ToList();

        // Fee ratio per valid (non-voided) invoice = OnlineFeeAmount / TotalNet.
        var feeRatioByInvoice = (await _invoices
                .Find(Builders<Invoice>.Filter.And(
                    Builders<Invoice>.Filter.In(i => i.Id, invoiceIds),
                    Builders<Invoice>.Filter.Ne(i => i.Status, "VOIDED")))
                .Project(i => new { i.Id, i.OnlineFeeAmount, i.TotalNet })
                .ToListAsync())
            .ToDictionary(
                i => i.Id!,
                i => i.TotalNet > 0m ? Math.Clamp(i.OnlineFeeAmount / i.TotalNet, 0m, 1m) : 0m);

        decimal revenue = 0m, fees = 0m;
        foreach (var p in payments)
        {
            if (string.IsNullOrEmpty(p.InvoiceId) || !feeRatioByInvoice.TryGetValue(p.InvoiceId, out var ratio))
                continue; // orphan / voided invoice — excluded entirely
            var fee = p.AmountPaid * ratio;
            fees += fee;
            revenue += p.AmountPaid - fee;
        }
        return (revenue, fees);
    }

