    public async Task<BusinessSummaryDto> GetBusinessSummaryAsync(AnalyticsRangeQuery range)
    {
        if (range == null) throw new ArgumentNullException(nameof(range));

        // Reuse the month-summary aggregation for revenue / clients / classes /
        // packages / bookings — it already handles any date window.
        var summary = await GetMonthSummaryAsync(range);

        // Operating expenses in the window (exclude CAPEX, matching the P&L /
        // daily-profit definition).
        var expenses = await _expenses
            .Find(Builders<Expense>.Filter.And(
                Builders<Expense>.Filter.Gte(e => e.DateIncurred, range.StartDate),
                Builders<Expense>.Filter.Lt(e => e.DateIncurred, range.EndDate),
                Builders<Expense>.Filter.Ne(e => e.Type, "CAPEX")))
            .ToListAsync();
        var expensesTotal = expenses.Sum(e => e.Amount);

        // Instructor commissions earned in the window (group + private earnings,
        // excluding base salary). Non-persisting payroll calc.
        var commissions = _payroll is null
            ? 0m
            : await _payroll.CalculateTotalCommissionsAsync(range.StartDate, range.EndDate);

        return new BusinessSummaryDto
        {
            RevenueVnd = summary.TotalRevenueVnd,
            ExpensesVnd = expensesTotal,
            CommissionsVnd = commissions,
            ProfitVnd = summary.TotalRevenueVnd - expensesTotal - commissions,
            NewClients = summary.NewClients,
            ClassesHeld = summary.TotalClasses,
            PackagesSold = summary.PackagesSold,
            Bookings = summary.TotalBookings,
        };
    }

    /// <inheritdoc />
    public async Task<List<DailyTimeSeriesDto>> GetDailyTimeSeriesAsync(AnalyticsRangeQuery range, string metric)
    {
        if (range == null) throw new ArgumentNullException(nameof(range));
        var lowerMetric = (metric ?? "revenue").ToLowerInvariant();

        if (lowerMetric == "revenue")
        {
            var payments = await _payments
                .Find(Builders<Payment>.Filter.And(
                    Builders<Payment>.Filter.Gte(p => p.PaymentDate, range.StartDate),
                    Builders<Payment>.Filter.Lt(p => p.PaymentDate, range.EndDate)))
                .Project(p => new { p.PaymentDate, p.AmountPaid })
                .ToListAsync();

            return payments
                .GroupBy(p => p.PaymentDate.Date)
                .Select(g => new DailyTimeSeriesDto { Date = g.Key, Value = g.Sum(p => p.AmountPaid) })
                .OrderBy(d => d.Date)
                .ToList();
        }

        if (lowerMetric == "classes")
        {
            var sessions = await _sessions
                .Find(Builders<CalendarSession>.Filter.And(
                    Builders<CalendarSession>.Filter.Gte(s => s.StartTime, range.StartDate),
                    Builders<CalendarSession>.Filter.Lt(s => s.StartTime, range.EndDate),
                    Builders<CalendarSession>.Filter.In(s => s.Status, new[] { "SCHEDULED", "COMPLETED" }),
                    Builders<CalendarSession>.Filter.Eq(s => s.IsFreelance, false)))
                .Project(s => new { s.StartTime })
                .ToListAsync();

            return sessions
                .GroupBy(s => s.StartTime.Date)
                .Select(g => new DailyTimeSeriesDto { Date = g.Key, Value = g.Count() })
                .OrderBy(d => d.Date)
                .ToList();
        }

        if (lowerMetric == "profit")
        {
            // Revenue minus daily-apportioned expenses
            var payments = await _payments
                .Find(Builders<Payment>.Filter.And(
                    Builders<Payment>.Filter.Gte(p => p.PaymentDate, range.StartDate),
                    Builders<Payment>.Filter.Lt(p => p.PaymentDate, range.EndDate)))
                .Project(p => new { p.PaymentDate, p.AmountPaid })
                .ToListAsync();

            var expenses = await _expenses
                .Find(Builders<Expense>.Filter.And(
                    Builders<Expense>.Filter.Gte(e => e.DateIncurred, range.StartDate),
                    Builders<Expense>.Filter.Lt(e => e.DateIncurred, range.EndDate),
                    Builders<Expense>.Filter.Ne(e => e.Type, "CAPEX")))
                .Project(e => new { e.DateIncurred, e.Amount })
                .ToListAsync();

            var revenueByDay = payments
                .GroupBy(p => p.PaymentDate.Date)
                .ToDictionary(g => g.Key, g => g.Sum(p => p.AmountPaid));

            var expenseByDay = expenses
                .GroupBy(e => e.DateIncurred.Date)
                .ToDictionary(g => g.Key, g => g.Sum(e => e.Amount));

            var allDates = revenueByDay.Keys.Union(expenseByDay.Keys).OrderBy(d => d);
            return allDates.Select(d => new DailyTimeSeriesDto
            {
                Date = d,
                Value = (revenueByDay.TryGetValue(d, out var r) ? r : 0m)
                      - (expenseByDay.TryGetValue(d, out var e) ? e : 0m),
            }).ToList();
        }

        throw new ArgumentException($"metric must be one of: revenue, classes, profit. Got: '{metric}'.", nameof(metric));
    }

