        ? new Dictionary<string, Product>()
        : (await _products
            .Find(Builders<Product>.Filter.In(p => p.Id, distinctProductIds))
            .ToListAsync())
            .Where(p => p.Id != null)
            .ToDictionary(p => p.Id!, p => p);

    decimal totalRevenue = 0m, singleClassRevenue = 0m, packageRevenue = 0m,
            merchandiseRevenue = 0m, rentalRevenue = 0m;

    foreach (var inv in paidInvoices)
    {
        var paidAmount = paidByInvoiceId.GetValueOrDefault(inv.Id ?? string.Empty);
        if (paidAmount <= 0m || inv.TotalNet <= 0m) continue;

        totalRevenue += paidAmount;
        var recognitionRatio = Math.Min(1m, paidAmount / inv.TotalNet);
        foreach (var line in inv.Lines)
        {
            var productType = line.ProductTypeSnapshot;
            if (string.IsNullOrEmpty(productType) && !string.IsNullOrEmpty(line.ProductId) && productsById.TryGetValue(line.ProductId, out var prod))
                productType = prod.Type;

            var recognizedLineTotal = (line.LineTotal > 0m
                ? line.LineTotal
                : (line.UnitPrice * line.Quantity) - line.LineDiscount) * recognitionRatio;

            switch (productType)
            {
                case "PACKAGE":
                    packageRevenue += recognizedLineTotal;
                    break;
                case "MERCHANDISE":
                    merchandiseRevenue += recognizedLineTotal;
                    break;
                case "FREELANCE_PACKAGE":
                case "FREELANCE_SINGLE":
                    rentalRevenue += recognizedLineTotal;
                    break;
                default:
                    // Check if line is tied to a session (class drop-in) or rental
                    if (!string.IsNullOrEmpty(line.CalendarSessionId))
                        singleClassRevenue += recognizedLineTotal;
                    else
                        singleClassRevenue += recognizedLineTotal; // Default bucket
                    break;
            }
        }
    }
    if (rentalRevenue <= 0m)
        rentalRevenue = Math.Max(0m, totalRevenue - singleClassRevenue - packageRevenue - merchandiseRevenue);
    if (rentalRevenue > 0) singleClassRevenue = totalRevenue - packageRevenue - merchandiseRevenue - rentalRevenue;

    // 2. Sessions actually HELD WITH ATTENDEES in the window: COMPLETED,
    //    non-freelance sessions that had at least one checked-in attendee.
    //    Scheduled (not yet held) and empty / all-no-show classes are excluded
    //    so class analytics reflect classes the studio actually taught.
    var completedSessions = await _sessions
        .Find(Builders<CalendarSession>.Filter.And(
            Builders<CalendarSession>.Filter.Gte(s => s.StartTime, range.StartDate),
            Builders<CalendarSession>.Filter.Lt(s => s.StartTime, range.EndDate),
            Builders<CalendarSession>.Filter.Eq(s => s.Status, "COMPLETED"),
            Builders<CalendarSession>.Filter.Eq(s => s.IsFreelance, false)))
        .ToListAsync();

    var completedSessionIds = completedSessions.Select(s => s.Id).ToList();
    var attendedSessionIds = completedSessionIds.Count == 0
        ? new HashSet<string?>()
        : (await _attendances.Distinct(
                a => a.CalendarSessionId,
                Builders<Attendance>.Filter.And(
                    Builders<Attendance>.Filter.In(a => a.CalendarSessionId, completedSessionIds),
                    Builders<Attendance>.Filter.In(a => a.Status, AttendedStatuses)))
            .ToListAsync())
            .ToHashSet();

    var sessions = completedSessions.Where(s => attendedSessionIds.Contains(s.Id)).ToList();

    var totalClasses = sessions.Count;
    var groupClasses = sessions.Count(s => s.Format == "GROUP" || s.Format == "MAT");
    var privateClasses = sessions.Count(s => s.Format == "PRIVATE" || s.Format == "DUO");

    // 3. Attendances in window
    var bookedStatuses = ActiveBookedStatuses;
    var sessionIds = sessions.Select(s => s.Id).ToList();
    var attendances = sessionIds.Count == 0
        ? new List<Attendance>()
        : await _attendances
            .Find(Builders<Attendance>.Filter.And(
                Builders<Attendance>.Filter.In(a => a.CalendarSessionId, sessionIds),
                Builders<Attendance>.Filter.In(a => a.Status, bookedStatuses)))
            .ToListAsync();

