public async Task<bool> VoidInvoiceAsync(string invoiceId, string reason)
{
    var invoice = await _invoices.Find(i => i.Id == invoiceId).FirstOrDefaultAsync();
    if (invoice == null) return false;
    if (invoice.Status == "VOIDED") return true; // already voided

    var update = Builders<Invoice>.Update
        .Set(i => i.Status, "VOIDED")
        .Set(i => i.Notes, $"[VOIDED] {reason}" + (string.IsNullOrWhiteSpace(invoice.Notes) ? "" : $"\n\nOriginal notes: {invoice.Notes}"));

    var result = await _invoices.UpdateOneAsync(i => i.Id == invoiceId, update);
    if (result.ModifiedCount > 0)
    {
        // Voiding cancels the sale, so its payments must stop counting as
        // revenue (the dashboard + P&L sum Payment records). The audit trail —
        // the original PAYMENT_RECEIVED events plus this VOID — preserves the
        // history, so removing the payment docs is a clean revenue reversal.
        var voidedPayments = await _payments.Find(p => p.InvoiceId == invoiceId).ToListAsync();
        var voidedTotal = voidedPayments.Sum(p => p.AmountPaid);
        var removedPayments = await _payments.DeleteManyAsync(p => p.InvoiceId == invoiceId);

        // Pull the voided revenue back out of the client's lifetime value (VIP driver).
        if (!string.IsNullOrWhiteSpace(invoice.ClientId) && voidedTotal != 0)
            await _clients.UpdateOneAsync(c => c.Id == invoice.ClientId,
                Builders<Client>.Update.Inc(c => c.LifetimeValue, -voidedTotal));

        await _audit.LogAsync(
            action: "VOID",
            entityType: "Invoice",
            entityId: invoiceId,
            entityLabel: invoice.InvoiceNumber,
            after: new { reason, previousStatus = invoice.Status, removedPayments = removedPayments.DeletedCount });
    }
    return result.ModifiedCount > 0;
}

